import sys, io, contextlib
import numpy as np
sys.path.insert(0, 'source')
from Pynite import FEModel3D

def build(load_dir='FY', load=10.0, tc='tension', plane='xy', subdivide=False, rot=0.0):
    model = FEModel3D()
    model.add_material('Steel', 29000.0, 11400.0, 0.30, 0.490/12.0**2)
    model.add_section('Section', 1.94, 3.0, 3.0, 0.0438)
    if plane == 'xy':
        pts = {'A': (0.,0.,0.), 'B': (100.,0.,0.), 'C': (0.,10.,0.), 'D': (0.,-10.,0.)}
    elif plane == 'xz':
        pts = {'A': (0.,0.,0.), 'B': (100.,0.,0.), 'C': (0.,0.,10.), 'D': (0.,0.,-10.)}
    else:
        pts = {'A': (0.,0.,0.), 'B': (0.,100.,0.), 'C': (0.,0.,10.), 'D': (0.,0.,-10.)}
    for k,v in pts.items():
        model.add_node(k, *v)
    if subdivide:
        # internal node on the M2 line, fully supported to keep model stable
        d, b = pts['D'], pts['B']
        model.add_node('E', (d[0]+b[0])/2, (d[1]+b[1])/2, (d[2]+b[2])/2)
        model.def_support('E', True, True, True, True, True, True)
    model.add_member('M0', 'A', 'B', 'Steel', 'Section')
    model.add_member('M1', 'C', 'B', 'Steel', 'Section', tension_only=(tc=='tension'), comp_only=(tc=='comp'))
    model.add_member('M2', 'D', 'B', 'Steel', 'Section', tension_only=(tc=='tension'), comp_only=(tc=='comp'), rotation=rot)
    for name in ('M0','M1','M2'):
        model.def_releases(name, Ryi=True, Rzi=True, Ryj=True, Rzj=True)
    for n in ('A','C','D'):
        model.def_support(n, True, True, True, True, True, True)
    if plane == 'xy':
        model.def_support('B', False, False, True, True, True, True)
        model.add_node_load('B', 'FY', load)
    else:
        model.def_support('B', False, False, False, True, True, True)
        model.add_node_load('B', 'FZ', load)
    with contextlib.redirect_stdout(io.StringIO()):
        model.analyze(log=False)
    return model

